function fail(e){return Promise.reject(new Error(e))}async function guarded(){try{await fail("boom-1"),print("unreachable")}catch(e){print("guarded caught:",e.message)}return"recovered"}async function unguarded(){return await fail("boom-2"),"unreachable"}guarded().then(function(e){print("guarded resolved:",e)}),unguarded().then(function(){print("unreachable-then")},function(e){print("unguarded rejected via .then handler:",e.message)});